const d = items[0].json;
const product = (d.product || '').toLowerCase();

// onalert, gutted, merciless retired from the OS control plane 2026-07-06 (Krish directive).
// Apps stay deployed until Krish sunsets them manually; do not route new proposals to them.
const repoMap = {
  'fractionl-pulse': 'krishanraja/fractionl-pulse',
  'fractionl-circle': 'krishanraja/fractionl-circle',
  'plinth': 'krishanraja/plinth',
  'full-time': 'krishanraja/full-time'
};

const repo = repoMap[product] || 'krishraja10101/fractionl';
const fallback = !repoMap[product];

const issueBody = `## Product Improvement Proposal
**Source:** Product Agent (autonomous) — approved by Agatha + Krish
**Evidence:** ${d.evidence || 'N/A'}
**Effort:** ${d.effort || 'unknown'} | **Impact:** ${d.impact || 'unknown'} | **Type:** ${d.type || 'feature'}

## Description
${d.description || 'No description provided.'}

## Acceptance Criteria
- [ ] Implementation matches description
- [ ] Tested in staging
- [ ] Agatha sign-off before production deploy`;

const issuePayload = JSON.stringify({
  title: `[Product Agent] ${d.title || 'Untitled Proposal'}`,
  body: issueBody,
  labels: ['product-agent', 'approved', d.type || 'feature']
});

const [owner, repoName] = repo.split('/');

return [{json: {
  issuePayload,
  repo,
  owner,
  repoName,
  title: d.title,
  fallback,
  product: d.product,
  proposal_id: d.proposal_id
}}];

const ghResponse = items[0].json;
const inputData = $('Build GitHub Issue Body').first().json;

const success = ghResponse.number && ghResponse.html_url;

if (success) {
  const tgMsg = `\u2705 GitHub issue #${ghResponse.number} created: [${inputData.title}](${ghResponse.html_url})${inputData.fallback ? '\n\u26a0\ufe0f Note: fallback repo used - ' + inputData.product + ' repo not found' : ''}`;
  return [{json: {success: true, issue_number: ghResponse.number, html_url: ghResponse.html_url, tgObject: {chat_id: 6773796504, text: tgMsg, parse_mode: 'Markdown'}, title: inputData.title}}];
} else {
  const errMsg = `\u26a0\ufe0f Failed to create GitHub issue for "${inputData.title}" (${inputData.product}). Error: ${ghResponse.message || 'Unknown'}. Manual action needed.`;
  return [{json: {success: false, tgObject: {chat_id: 6773796504, text: errMsg, parse_mode: 'Markdown'}, title: inputData.title}}];
}

// Injected fetch-based httpRequest shim (task-runner-safe)
const __helpers = this.helpers;
async function __httpRequest(opts) {
  const method = (opts.method || 'GET').toUpperCase();
  const url = opts.url;
  const headers = Object.assign({}, opts.headers || {});
  const cfg = {
    method,
    url,
    headers,
    json: opts.json !== false,
    returnFullResponse: true,
    timeout: opts.timeout || 30000,
  };
  if (opts.body !== undefined && opts.body !== null) {
    cfg.body = opts.body;
    if (typeof opts.body === 'object' && !headers['Content-Type'] && !headers['content-type']) {
      cfg.headers['Content-Type'] = 'application/json';
    }
  }
  let res;
  try {
    res = await __helpers.httpRequest(cfg);
  } catch (err) {
    const status = err.httpCode || err.statusCode || (err.response && err.response.status) || 0;
    const body = (err.response && err.response.body) || err.body || null;
    const wrapped = new Error('HTTP ' + (status || 'network') + ': ' + (err.message || String(err)).slice(0, 300));
    wrapped.httpCode = status;
    wrapped.body = body;
    throw wrapped;
  }
  const status = res.statusCode || res.status || 0;
  const body = res.body !== undefined ? res.body : res;
  if (status < 200 || status >= 300) {
    const e = new Error('HTTP ' + status + ': ' + String(body).slice(0, 300));
    e.httpCode = status;
    e.body = body;
    throw e;
  }
  return body;
}

let startTime = Date.now();
try {
  startTime = $('Webhook').first().json.headers['x-request-start'];
} catch(e) {
  // Ignore missing webhook node
}
const duration = Date.now() - (parseInt(startTime) || Date.now());

const payload = {
  workflow_id: $workflow.id,
  workflow_name: $workflow.name,
  agent_id: $input.first()?.json?.agent_id || 'system',
  duration_ms: duration,
  api_calls: $input.first()?.json?.api_call_count || 0,
  cost_usd: $input.first()?.json?.total_cost || 0,
  outcome: $input.first()?.json?.outcome || 'completed',
  outcome_count: $input.first()?.json?.result_count || 0,
  quality_score: $input.first()?.json?.quality_score || null,
  status: 'success',
  metadata: JSON.stringify({ source: 'n8n_auto_log' })
};

const response = await __httpRequest({
  method: 'POST',
  url: 'https://gojpffsrxybbpbdzzrvs.supabase.co/rest/v1/workflow_runs',
  headers: {
    'apikey': '{{SUPABASE_SERVICE_ROLE_KEY}}',
    'Authorization': 'Bearer {{SUPABASE_SERVICE_ROLE_KEY}}',
    'Content-Type': 'application/json',
    'Prefer': 'return=representation'
  },
  body: payload,
  json: true
});

return [{ json: { logged: true, ...payload } }];
